#!/bin/bash
# Codex scene prompts (real glasses attached with -i). Each run costs ChatGPT quota.
cd /c/timeoptic-content
K=kits/2026-11-09_prada-linea-rossa-sail
KEEP="Use the attached sunglasses exactly as they are: same shape, proportions, matte black frame, light-blue rubber inserts, blue mirror lenses, temples and hinges; the red bar on the temple stays exactly as in the photo. Do not redesign, restyle, recolor or add any logo, text or extra parts. The glasses are the hero, sharp and in focus, with a realistic contact shadow and believable reflections of the scene."
STYLE="Square 1:1 luxury eyewear advertising photograph, cinematic, shot on a medium-format camera with a 100mm macro lens, shallow depth of field. Absolutely no text, no letters, no watermark, no logos anywhere in the image. Leave calm dark negative space in the top 18% and bottom 12% of the frame for a logo overlay."
run () { codex exec -m gpt-5.6-luna -c model_reasoning_effort="low" -C "$PWD" --skip-git-repo-check -s workspace-write -i "$2" -o tmp/codex-$1.txt "Call the built-in image_gen tool exactly once with the prompt below, verbatim, using the attached image as the product reference. Do not rewrite the prompt, do not generate variants, do not inspect or edit the result. Reply with only the saved file path. PROMPT: $3" > tmp/codex-$1.log 2>&1; }
run front $K/layers/front.png "$STYLE The attached sunglasses, seen straight from the front, rest on the wet carbon-fibre deck of a racing sailboat at dusk, slightly angled toward the camera. Behind them, out of focus, a taut dark sail, rigging lines and a deep navy ocean with white spray; a low orange sunset sits on the horizon and rims the frame with warm light, while the blue mirror lenses reflect the sky and the sail. Water droplets beaded on the deck. Palette: deep navy, charcoal black, a touch of warm orange, a single thin streak of red from a rope. Moody, premium, sporty. $KEEP" &
run side $K/layers/side.png "$STYLE The attached sunglasses in exact side profile, temple running left to right, standing on the polished wet carbon-fibre rail of a racing sailboat at dusk, camera at the height of the temple so the red bar on the temple reads clearly. Behind, out of focus, sea spray caught in backlight, a dark navy ocean and a thin orange sunset line on the horizon. Tiny water droplets on the matte black frame. Palette: deep navy, charcoal black, warm orange rim light. Moody, premium, sporty. $KEEP" &
run back $K/layers/back.png "$STYLE The attached sunglasses seen from behind and slightly above, temples open toward the camera, resting on a coiled dark-grey sailing rope on the wet deck of a racing sailboat at dusk; the light-blue inner rubber inserts catch a soft cool light. Background out of focus: a dark sail edge, navy ocean, spray and a low orange sunset glow. Palette: deep navy, charcoal black, light blue, warm orange rim light. Moody, premium, sporty. $KEEP" &
wait
